import urllib.request
import urllib.error
import time
from typing import Optional

class RateLimitError(Exception):
    """Raised when the API returns a 429 Too Many Requests."""
    pass

class ServerError(Exception):
    """Raised when the API returns a 5xx error after retry."""
    pass

class ClientError(Exception):
    """Raised when the API returns a 4xx error (except 429)."""
    pass

class ConnectionError(Exception):
    """Raised when a network error occurs after retry."""
    pass

class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str) -> str:
        url = self.base_url.rstrip('/') + path.lstrip('/')
        req = urllib.request.Request(url, method='GET')
        return self._do_request(req)

    def _do_request(self, req: urllib.request.Request) -> str:
        retries = {
            'rate_limit': 3,
            'server': 1,
            'client': 0,
            'connection': 1,
        }
        backoff = {
            'rate_limit': [0.5, 1.0, 2.0],
            'server': [1.0],
            'client': [],
            'connection': [1.0],
        }

        while True:
            try:
                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                    body = resp.read().decode('utf-8')
                    status = resp.status
            except urllib.error.HTTPError as e:
                status = e.code
                body = e.read().decode('utf-8')
            except urllib.error.URLError as e:
                body = str(e.reason)
                status = 0

            if status == 429:
                if retries['rate_limit'] > 0:
                    retries['rate_limit'] -= 1
                    delay = backoff['rate_limit'][retries['rate_limit']]
                    time.sleep(delay)
                    continue
                raise RateLimitError("Rate limit exceeded after retries.")

            if 500 <= status <= 599:
                if retries['server'] > 0:
                    retries['server'] -= 1
                    time.sleep(1.0)
                    continue
                raise ServerError(f"Server error {status}: {body}")

            if 400 <= status <= 499 and status != 429:
                raise ClientError(f"Client error {status}: {body}")

            if status == 0:
                if retries['connection'] > 0:
                    retries['connection'] -= 1
                    time.sleep(1.0)
                    continue
                raise ConnectionError(f"Connection error: {body}")

            # Any other status (e.g., 200) -> return body
            return body

    def get(self, path: str) -> str:
        return self._make_request(path)
